<?php
$loaded=max(0,(float)$b['actual_input_quantity_kg']);$flour=max(0,(float)$b['output_quantity_kg']);$waste=max(0,(float)$b['waste_quantity_kg']);$gap=round($loaded-$flour-$waste,3);$denominator=max($loaded,$flour+$waste);$segments=$denominator>0?[100*$flour/$denominator,100*$waste/$denominator,100*max(0,$gap)/$denominator]:[0,0,0];
?>
<div class="prod-balance"><div class="prod-balance-bar" role="img" aria-label="<?=e('Farine : '.$kg($flour).', déchets : '.$kg($waste).', '.($gap<0?'dépassement':'écart').' : '.$kg(abs($gap)))?>"><span class="is-flour" style="width:<?=e($segments[0])?>%"></span><span class="is-waste" style="width:<?=e($segments[1])?>%"></span><span class="is-gap" style="width:<?=e($segments[2])?>%"></span></div><div class="prod-balance-labels"><span class="is-flour">Farine <strong><?=e($kg($flour))?></strong></span><span class="is-waste">Déchets <strong><?=e($kg($waste))?></strong></span><span class="is-gap"><?=$gap<0?'Dépassement':'Écart'?> <strong><?=e($kg(abs($gap)))?></strong></span></div><?php if($gap<0):?><p class="prod-overrun">Les sorties dépassent le chargement de <?=e($kg(-$gap))?>.</p><?php endif;?></div>
